"""Exercise the bundle generated by submission.yaml across the task-file boundary."""
import asyncio
import json
from pathlib import Path
import shlex
import subprocess
import sys
import tempfile
import unittest
from unittest.mock import patch

import engineering_intake as intake


class TaskDirectory:
    def __init__(self, root, *, limit=10_000_000, corrupt=False):
        self.root = root
        self.limits = {"max_write_bytes": limit}
        self.corrupt = corrupt
        self.writes = []
        self.executions = 0

    async def write_file(self, path, data, append=False):
        assert len(data) <= self.limits["max_write_bytes"]
        self.writes.append(len(data))
        target = self.root / Path(path).name
        with target.open("ab" if append else "wb") as out:
            out.write(data)
        return target.stat().st_size

    async def exec(self, command, timeout_sec):
        self.executions += 1
        argv = shlex.split(command)
        assert argv[:3] == ["python3", "-I", "-c"]
        archive = self.root / Path(argv[-2]).name
        if self.corrupt:
            with archive.open("ab") as stream:
                stream.write(b"wrong bytes")
        argv[-2] = str(archive)
        result = subprocess.run(argv, cwd=self.root, capture_output=True, text=True, timeout=timeout_sec)
        return {"exit_code": result.returncode, "output": result.stdout}


class BuiltToolkit(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.TemporaryDirectory()
        cls.addClassCleanup(cls.tmp.cleanup)
        cls.bundle = Path(cls.tmp.name) / "engineering-toolkit.zip"
        intake.build_toolkit(cls.bundle)

    def test_all_sources_reach_task_and_cli_audits_public_workbook(self):
        root = Path(intake.__file__).parent
        expected = dict(intake._toolkit_sources(root))
        workbook = next((root / "artifacts/fill-compaction-acceptance/files").rglob("*.xlsx"))
        with tempfile.TemporaryDirectory() as task, patch.object(intake, "_BUILT_TOOLKIT", self.bundle):
            task = Path(task)
            remote = TaskDirectory(task)
            note = asyncio.run(intake.provision_engineering_cli(remote))
            self.assertIn("xlsx-audit", note)
            self.assertEqual(remote.writes, [self.bundle.stat().st_size])
            self.assertEqual(remote.executions, 1)
            self.assertEqual({p.name: p.read_bytes() for p in task.iterdir()}, expected)
            args = ["xlsx-audit", str(workbook)]
            def audit(cli):
                return json.loads(subprocess.check_output(
                    [sys.executable, "-E", "-s", str(cli), *args], cwd=task))
            self.assertEqual(audit(task / "hamon-engineering-toolkit.py"), audit(root / "engineering_toolkit.py"))

    def test_chunk_limit_and_corrupt_archive(self):
        with tempfile.TemporaryDirectory() as task, patch.object(intake, "_BUILT_TOOLKIT", self.bundle):
            task = Path(task)
            remote = TaskDirectory(task, limit=24_000, corrupt=True)
            self.assertEqual(asyncio.run(intake.provision_engineering_cli(remote)), "")
            self.assertEqual(sum(remote.writes), self.bundle.stat().st_size)
            self.assertGreater(len(remote.writes), 1)
            self.assertEqual(list(task.iterdir()), [])
            remote.corrupt = False
            self.assertIn("xlsx-audit", asyncio.run(intake.provision_engineering_cli(remote)))
